<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import axios from 'axios';import CodeEditor from '../components/CodeEditor.vue';import {installAntiCheat} from '../utils/antiCheat';
const examId='demo';const question=ref<any>({id:'',title:'Loading…'});const code=ref('');const version=ref(0);const saved=ref('Not saved');const output=ref('');const remaining=ref(0);let timer:any,stopCheat:()=>void;
async function load(){const r=await axios.get(`/api/v1/exams/${examId}`);question.value=r.data.questions[0];const d=await axios.get(`/api/v1/exams/${examId}/questions/${question.value.id}/draft`);code.value=d.data.code;version.value=d.data.version;remaining.value=r.data.remaining_seconds||0}
async function save(){const r=await axios.put(`/api/v1/exams/${examId}/questions/${question.value.id}/draft`,{code:code.value,version:version.value});version.value=r.data.version;saved.value=`Saved ${new Date().toLocaleTimeString()} · v${version.value}`}
let debounce:any;watch(code,()=>{clearTimeout(debounce);debounce=setTimeout(save,2000)});async function sample(){const r=await axios.post(`/api/v1/exams/${examId}/questions/${question.value.id}/run-sample`,{code:code.value});output.value=`Queued ${r.data.sample_cases} sample case(s)`}async function submit(){if(confirm('Submit the entire exam? This cannot be undone.'))await axios.post(`/api/v1/exams/${examId}/submit`,{confirm:true})}onMounted(async()=>{await load();stopCheat=installAntiCheat(examId);timer=setInterval(()=>{if(remaining.value>0)remaining.value--},1000)});onBeforeUnmount(()=>{stopCheat?.();clearInterval(timer);clearTimeout(debounce)});
</script><template><main><header><h1>LabProctor OJ</h1><span>Time left: {{Math.floor(remaining/60)}}:{{String(remaining%60).padStart(2,'0')}}</span></header><section><aside><h2>{{question.title}}</h2><p>{{question.statement}}</p><button @click="sample">Run sample</button><p>{{saved}}</p><pre>{{output}}</pre></aside><article><CodeEditor v-model="code" /></article></section><footer><button @click="save">Save now</button><button class="submit" @click="submit">Submit entire exam</button></footer></main></template><style scoped>main{font:14px system-ui;background:#f5f7fb;min-height:100vh;padding:20px}header,footer{display:flex;justify-content:space-between;align-items:center;background:white;padding:12px 20px;border-radius:8px}section{display:grid;grid-template-columns:30% 70%;gap:12px;margin:12px 0}aside{background:white;padding:16px;border-radius:8px}button{padding:8px 14px;border:0;border-radius:5px;cursor:pointer}.submit{background:#b42318;color:white}pre{white-space:pre-wrap;background:#111;color:#9fe870;padding:10px}</style>
